$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'

"use strict";
const fs=require("fs"), assert=require("assert"),crypto=require("crypto");
const paths={
 unaliased:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json",
 aliased:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json",
 lookup:"references/instruction-wrapper-key-aliases.json",
 task:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json"
};
const read=p=>JSON.parse(fs.readFileSync(p,"utf8"));
const write=(p,x,compact=false)=>fs.writeFileSync(p,JSON.stringify(x,null,compact?0:2)+"\n");
const prior=read(paths.unaliased),priorAlias=read(paths.aliased),lookup=read(paths.lookup),task=read(paths.task);
assert(Array.isArray(prior)&&prior.length===3);
assert(priorAlias[0].alias_lookup_path===paths.lookup);
assert(!Object.hasOwn(prior[0],"reference_base_url"));
assert(!Object.hasOwn(prior[0],"reference_resolution"));
assert(task.status==="pending_revision");
const base="https://raw.githubusercontent.com/BestNameYet/Terminals/main/";
const required="Every relative file path in this instruction collection is rooted at the top level of GitHub repository BestNameYet/Terminals on branch main. To retrieve a referenced file, use the GitHub integration with repository BestNameYet/Terminals, branch main, and the stated path, or append that path to reference_base_url to obtain its raw-file URL. Destination paths identify files to write in that same repository; substitute defined filename variables before writing. Do not search other storage providers for these paths.";
const revised=structuredClone(prior);
revised[0].reference_base_url=base;
revised[0].reference_resolution=required;
assert.deepStrictEqual(revised[1],prior[1]);
assert.deepStrictEqual(revised[2],prior[2]);
const aliases={...lookup.alias_to_key};
assert(aliases.r==="rules_template_path"&&aliases.ga==="github_repository_documentation_preflight");
assert(!Object.hasOwn(aliases,"ra"));
assert(!Object.values(aliases).includes("reference_resolution"));
aliases.ra="reference_resolution";
const reverse=new Map(Object.entries(aliases).map(([alias,key])=>[key,alias]));
function encode(v){
 if(Array.isArray(v))return v.map(encode);
 if(v===null||typeof v!=="object")return v;
 const o={};for(const [k,x]of Object.entries(v)){if(k==="reference_base_url"){o.reference_base_url=x;continue;}const alias=reverse.get(k);assert(alias,"Missing alias "+k);o[alias]=encode(x);}return o;
}
function decode(v){
 if(Array.isArray(v))return v.map(decode);
 if(v===null||typeof v!=="object")return v;
 const o={};for(const [k,x]of Object.entries(v)){
  const key=(k==="reference_base_url"||k==="alias_lookup_path")?k:aliases[k];
  assert(key,"Missing key name for "+k);
  o[key]=decode(x);
 }return o;
}
const encoded=encode(revised);
encoded[0].alias_lookup_path=paths.lookup;
assert(encoded[0].reference_base_url===base);
assert(encoded[0].ra===required);
const recovered=decode(encoded);delete recovered[0].alias_lookup_path;
assert.deepStrictEqual(recovered,revised);
const encountered=new Set();
function walk(v){if(Array.isArray(v))return v.forEach(walk);if(v===null||typeof v!=="object")return;for(const [k,x]of Object.entries(v)){encountered.add(k);walk(x);}}
walk(revised);
assert(encountered.size===Object.keys(aliases).length+1);
for(const [alias,key]of Object.entries(aliases)){assert(alias[0]===key[0]&&alias.length<=2);}
lookup.alias_to_key=aliases;
lookup.original_key_count=encountered.size;
lookup.total_key_count_including_lookup=encountered.size;
lookup.aliases_with_one_character=Object.keys(aliases).filter(k=>k.length===1).length;
lookup.aliases_with_two_characters=Object.keys(aliases).filter(k=>k.length===2).length;
lookup.source_template_sha256=crypto.createHash("sha256").update(JSON.stringify(revised,null,2)+"\n").digest("hex");
lookup.mapping_semantics.additional_lookup_member="In the aliased copy, the outer index-zero explainer exposes the literal alias_lookup_path and reference_base_url members without aliasing. These bootstrap values let an agent locate the GitHub repository and fetch the alias dictionary before interpreting any encoded key names. All other names use their allocated aliases.";
lookup.mapping_semantics.decoding="Read reference_base_url and alias_lookup_path from the outer index-zero explainer, fetch the lookup file by resolving alias_lookup_path against reference_base_url, and decode all other object-member aliases recursively using alias_to_key. Preserve the literal reference_base_url and remove the alias_lookup_path bootstrap-only member to reconstruct the unaliased draft.";
task.task.amendments.push({
 purpose:"Make relative instruction reference paths independently resolvable to an identified GitHub repository and branch.",
 user_instruction_summary:"The relative paths are ambiguous without a base storage location; specify the source repository, branch, and a direct retrieval mechanism in the wrapper.",
 implementation:"Add reference_base_url and reference_resolution to outer index zero. Keep reference_base_url and alias_lookup_path literal in the aliased copy so the alias map can be retrieved before decoding. Preserve all existing rule entries and relative paths.",
 status:"pending_user_review"
});
write(paths.unaliased,revised);
write(paths.aliased,encoded,true);
write(paths.lookup,lookup);
write(paths.task,task);
const remote=read(paths.aliased);
const check=decode(remote);delete check[0].alias_lookup_path;
assert.deepStrictEqual(check,read(paths.unaliased));
assert.deepStrictEqual(read(paths.unaliased)[1],prior[1]);
assert.deepStrictEqual(read(paths.unaliased)[2],prior[2]);
assert(read(paths.lookup).alias_to_key.ra==="reference_resolution");
assert(read(paths.task).status==="pending_revision");
console.log("REFERENCE_BASE_URL",base);
console.log("REFERENCE_RESOLUTION",required);
console.log("LITERAL_BOOTSTRAP_KEYS",Object.keys(remote[0]).filter(k=>["reference_base_url","alias_lookup_path"].includes(k)).join(","));
console.log("INDEX_ZERO_KEYS",JSON.stringify(Object.keys(revised[0])));
console.log("UNCHANGED_RULES",true);
console.log("ROUNDTRIP_VERIFIED",true);
console.log("DRAFT_CHARACTER_COUNT",fs.readFileSync(paths.unaliased,"utf8").length);
console.log("ALIAS_CHARACTER_COUNT",fs.readFileSync(paths.aliased,"utf8").length);

NODE
git add -- 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json' 'references/instruction-wrapper-key-aliases.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json'
git diff --cached --check
git commit -m 'Bind instruction references to Terminals GitHub repository and main branch'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT ';git rev-parse HEAD
git show --stat --oneline HEAD
